<template>
  <v-col class="mt-0 pt-0">
    <div class="d-flex justify-center">
      <v-btn
          :class="{ 'active-btn': mobile }"
          @click="mobile = true; tablet = false; this.initCheckout('#checkout-container-mobile')"
          size="large"
          variant="plain"
          icon="mdi-cellphone">
      </v-btn>
      <v-btn
          :class="{ 'active-btn': tablet }"
          @click="tablet = true; mobile = false; this.initCheckout('#checkout-container-tablet')"
          size="large"
          variant="plain"
          icon="mdi-tablet">

      </v-btn>
    </div>
    <div v-if="mobile" class="d-flex flex-row justify-center pa-md-10 position-relative pt-0">
      <v-img
          class="c-img"
          width="260"
          :src="mobile_frame">
      </v-img>
      <div class="c-content flitt-checkout" id="checkout-container-mobile"></div>
    </div>
    <div v-if="tablet" class="d-flex flex-row justify-center pa-md-10 position-relative pt-0">
      <v-img
          class="c-img-tablet"
          width="460"
          :src="tablet_frame">
      </v-img>
      <div class="c-content-tablet flitt-checkout" id="checkout-container-tablet"></div>
    </div>
  </v-col>
</template>

<script>
import colors from "@/utils/colors.js";
import mobile_frame from "@/assets/images/phone_frame.svg";
import tablet_frame from "@/assets/images/tablet.png";

export default {
  name: "MobileWidget",
  props: {
    amount: 0,
    src: '',
    checkoutOptions: {
      type: Object,
      default: {
        options: {
          methods: ["card"],
          methods_disabled: ["wallets"],
          card_icons: ["mastercard", "visa"],
          fields: false,
          full_screen: false,
          button: true,
          hide_title: true,
          hide_link: true,
          email: false,
          theme: {
            type: "light",
            preset: "reset"
          },
          loading:
              "data:image/svg+xml;base64,",
        },
        params: {
          lang: 'en',
          merchant_id: 1549901,
          required_rectoken: "y",
          currency: "GEL"
        },
        css_variable: {
          main: colors.primary,
          card_bg: '#353535',
          card_shadow: '#9ADBE8'
        }
      },
    }
  },
  methods: {
    initCheckout(container) {
      window.checkout(container, this.checkoutOptions);
    },
  },

  mounted() {
    this.checkoutOptions.params.amount = this.amount * 100;
    this.initCheckout("#checkout-container-mobile")
  },
  data() {
    return {
      mobile: true,
      tablet: false,
      mobile_frame: mobile_frame,
      tablet_frame: tablet_frame,
      colors: colors,
    };
  },

};
</script>
